import unittest,re
from tools.kjv_archive import load_register,read
class HebrewsQuotedSelfTests(unittest.TestCase):
 def test_quoted_selves_and_rest(self):
  prior,_=load_register('0.10-kjv.258');lang,manifest=load_register('0.10-kjv.259')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('hebrews-'):c for c in read(lang.folder/'hebrews-quoted-selves-and-rest-cases.json')};self.assertEqual(len(cases),51)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'1:1': ['different time:pl', 'different manner:pl', 'to father:pl by prophet:pl'], '1:2': ['to wesg by his/son', 'all thing:pl heir', 'world:pl make:pa'], '1:3': ['his/kjv_person_being_hebrews exact image', 'by himself ourone/sin:pl purge:perf', 'majesty kjv_right_side hand'], '1:4': ['better than angel:pl', 'by inheritance more excellent name'], '1:5': ['thou mypl/son', 'this day ipl thou:a beget:perf', 'ipl to he father be:fu and he to ipl son'], '1:6': ['kjv_firstborn_human into world', 'all god angel:pl he:a kjv_worship:opt'], '1:7': ['his/angel:pl spirit:pl', 'his/kjv_minister:pl fire flame'], '1:8': ['to son he say:pr', 'thy/throne kjv_vocative god', 'kjv_righteousness sceptre thy/kingdom sceptre'], '1:9': ['god even thy/god', 'joy oil above thy/companion:pl'], '1:10': ['earth kjv_foundation lay:perf', 'heaven:pl thy/hand:pl work:pl'], '1:11': ['they perish:fu but thou remain:pr', 'as garment old become:fu'], '1:12': ['as clothing thou they:a up kjv_fold_cloth_hebrews:fu', 'thou same be:pr', 'thy/year:pl fail:neg:fu'], '1:13': ['on mypl/kjv_right_side hand sit:imp', 'ipl thy/enemy:pl thy/kjv_footstool'], '1:14': ['serve:cv spirit:pl be:neg:pr:q', 'salvation heir:pl be:fu serve:inf'], '2:1': ['wesg hear:perf more earnest heed', 'wesg they:a kjv_slip_away_hebrews:caus:should'], '2:2': ['word by angel:pl speak:psv:pp', 'every transgress:ev and disobedience', 'kjv_righteous reward recompense'], '2:3': ['how wesg escape:fu:q', 'at first by kjv_lord', 'to wesg by they who he:a hear:pa'], '2:4': ['god also to they testimony', 'different miracle:pl', 'kjv_holy_spirit_title gift:pl', 'his/own will'], '2:5': ['to angel:pl', 'world which come:pr', 'wesg speak:pr', 'kjv_subject_authority_romans:neg:perf'], '2:6': ['person in particular place testify:pa', 'what man', 'man son', 'visit:pr:q'], '2:7': ['little more low than angel:pl', 'glory and honour crown:pa', 'over thy/hand:pl work:pl set:pa'], '2:8': ['all thing:pl under his/foot:pl', 'he nothing', 'wesg yet all thing:pl', 'see:neg:pr'], '2:9': ['wesg kjv_jesus_matthew', 'for death suffer:ev', 'for every man death taste:should'], '2:10': ['for who all thing:pl', 'by who all thing:pl', 'many son:pl to glory', 'through suffer:ev:pl perfect'], '2:11': ['he who sanctify:pr and they who sanctify:psv:pr all of one_num', 'brother:pl call:inf shame:psv:neg:pr'], '2:12': ['ipl thy/name to mypl/brother:pl', 'kjv_church_assembly ipl to thou praise sing:fu'], '2:13': ['ipl mypl/trust in he put:fu', 'ipl and child:pl which god to ipl give:perf'], '2:14': ['child:pl flesh and blood', 'he also himself likewise same share:pa', 'death power', 'devil'], '2:15': ['through death fear all their/life time', 'bondage submit:psv:pa'], '2:16': ['on himself angel:pl nature take:neg:pa', 'on himself kjv_abraham offspring take:pa'], '2:17': ['like his/brother:pl', 'mercy:adj and faithful high priest', 'people sin:pl kjv_reconcile_ritual:inf'], '2:18': ['he himself kjv_tempt_trial_hebrews:psv:cv suffer:perf', 'kjv_tempt_trial_hebrews:psv:pr help:inf able'], '3:1': ['ourone/acknowledge:ev kjv_apostle and high priest', 'kjv_christ_title kjv_jesus_matthew'], '3:2': ['to he who he:a appoint:pa', 'kjv_moses in all his/house'], '3:3': ['this man more glory than kjv_moses', 'worthy reckon:psv:pa', 'more honour than house'], '3:4': ['every house by some man', 'all thing:pl build:pa god'], '3:5': ['as servant faithful', 'testimony', 'afterward speak:psv:inf'], '3:6': ['son over his/own house', 'whose house wesg', 'if wesg', 'kjv_steadfast until end'], '3:7': ['kjv_holy_spirit_title say:pr', 'today if you his/voice hear:fu'], '3:8': ['your/heart:pl hard:caus:neg:imp', 'kjv_wilderness kjv_tempt_trial_hebrews:ev day'], '3:9': ['ipl:a kjv_tempt_trial_hebrews:pa ipl:a test:pa', 'mypl/work:pl three+twelve and four year:pl'], '3:10': ['ipl with that generation', 'they always in their/heart err:pr', 'mypl/way:pl know:neg:perf'], '3:11': ['ipl in mypl/wrath swear:pa', 'into mypl/rest:ev enter:neg:fu'], '3:12': ['in any of you', 'believe:neg:ev evil heart', 'from live:cv god depart:ev'], '3:13': ['each other daily', 'while it today call:psv:pr', 'through sin deceitful:ev'], '3:14': ['wesg kjv_christ_title share:cv person:pl', 'if wesg ourone/confidence beginning', 'until end'], '3:15': ['today if you his/voice hear:fu', 'your/heart:pl hard:caus:neg:imp'], '3:16': ['some when hear:perf kjv_provoke:pa', 'yet not all', 'out of egypt'], '3:17': ['three+twelve and four year:pl', 'whose kjv_corpse:pl in kjv_wilderness fall:pa'], '3:18': ['into his/rest:ev enter:neg:should', 'they who believe:neg:pa'], '3:19': ['wesg that because believe:neg:ev', 'enter:neg:can:pa see:pr']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('his/kjv_person_being_hebrews exact image',cases['1-3']['analysis'])
  self.assertIn('ipl to he father be:fu and he to ipl son',cases['1-5']['analysis'])
  self.assertIn('thy/throne kjv_vocative god',cases['1-8']['analysis'])
  self.assertIn('god even thy/god',cases['1-9']['analysis'])
  self.assertIn('they:a kjv_slip_away_hebrews:caus',cases['2-1']['analysis'])
  self.assertIn('all of one_num',cases['2-11']['analysis'])
  self.assertIn('ipl thy/name to mypl/brother:pl',cases['2-12']['analysis'])
  self.assertIn('on himself angel:pl nature take:neg:pa',cases['2-16']['analysis'])
  self.assertIn('kjv_holy_spirit_title say:pr',cases['3-7']['analysis'])
  self.assertIn('mypl/work:pl three+twelve and four year:pl',cases['3-9']['analysis'])
  self.assertIn('yet not all',cases['3-16']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),5)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
